CREATE TABLE employees(user_id INTEGER PRIMARY KEY,name TEXT NOT NULL,role TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1,started INTEGER NOT NULL DEFAULT 0);
CREATE TABLE tasks(id INTEGER PRIMARY KEY,title TEXT NOT NULL,creator INTEGER NOT NULL REFERENCES employees(user_id),assignee INTEGER NOT NULL REFERENCES employees(user_id),due_at INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'new',version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE history(id INTEGER PRIMARY KEY,task_id INTEGER NOT NULL REFERENCES tasks(id),actor INTEGER NOT NULL,action TEXT NOT NULL,created_at INTEGER NOT NULL);

CREATE TABLE updates(update_id INTEGER PRIMARY KEY);
CREATE TABLE outbox(
 id INTEGER PRIMARY KEY, event_key TEXT UNIQUE NOT NULL, chat_id INTEGER NOT NULL,
 payload TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'pending', attempts INTEGER NOT NULL DEFAULT 0,
 next_at INTEGER NOT NULL DEFAULT 0, message_id INTEGER, error_code INTEGER,
 guard_kind TEXT NOT NULL DEFAULT '', guard_id INTEGER, guard_version INTEGER
);
CREATE INDEX outbox_due ON outbox(state,next_at);

SELECT id,creator,assignee,due_at,status,version FROM tasks WHERE id=1;
SELECT actor,action,created_at FROM history WHERE task_id=1 ORDER BY id;
SELECT event_key,state,message_id FROM outbox ORDER BY id DESC LIMIT 20;
